presets.prompt:
{subject}, {
  "身份参考": {
    "来源": "上传的照片",
    "锁定": ["面部", "眼睛/鼻子/嘴巴", "肤色", "头发（长度/质地/颜色）", "配饰", "确切的服装"],
    "规则": "禁止编造细节"
  },
  "构图": {"格式": "纵向 4:5/9:16", "人物": ["真实主体", "墨迹孪生涂鸦"], "布局": "并排，姿势完全可见"},
  "真实主体": {"风格": "写实摄影，全身", "服装": "完全匹配参考图", "表情": "俏皮、尴尬、被抓包的魅力", "姿势": "自然、收敛的版本"},
  "墨迹孪生": {
    "风格": "墙面上的粗糙黑色素描/木炭涂鸦",
    "辨识度": "仅限轮廓（发型/服装/姿势形状）",
    "避免": ["写实的第二个人", "扁平的阴影", "彩色卡通"],
    "能量": "相对于真实主体更夸张、更混乱",
    "额外元素": "可选的稀疏漫画标记（动感线/星星/爱心）"
  },
  "姿势规则": {
    "指令": "每次都是全新的俏皮/恶作剧共享姿势",
    "避免": ["指点", "手指枪", "镜像/重复的姿势"],
    "关系": "主体 = 微妙版本；孪生体 = 夸张的卡通版本，同样的节奏"
  },
  "场景": {"背景": "干净简约的墙面（白色/奶油色/灰色）", "光照": "柔和、均匀、日光风格、面部清晰可见"},
  "情绪": "俏皮、时尚、混乱的趣味、适合分享",
  "负向提示词": [
    "编造的外貌", "服装变更", "将孪生体视为真实的第二个人",
    "扁平/诡异的阴影", "彩色卡通孪生体", "形似度低",
    "杂乱", "重复/僵硬/镜像的姿势", "文字", "水印",
    "多余肢体", "糟糕的手部"
  ]
}

{subject}, 16:9 曼哈顿天际线 1300-2025

:root {
    --subject: "$主体在漫长时光中的变迁"; /* 例如：1600-2100年的曼哈顿天际线、马的进化、英语语言 */
    --epochs: 5; /* AI 推断关键的代表性时代 */
}

# canvas {
    background: linear-gradient(to right, # f4e4c1, # 2c2c2c); /* 时间的黎明到黄昏 */
}

# subject_render {
    layout: "带垂直深度切片的水平三联画时间轴";
    render-left-panel: "黎明时代：高度风格化的历史艺术（木刻、泥金装饰手抄本、化石素描），带有相应时代字体的当代描述性标签。";
    render-middle-panels: "相继时代平滑过渡：每个时代使用其主流艺术和文献风格（银版照相、新闻短片、CAD 线框图），AI 推断建筑或形态细节。";
    render-right-panel: "远未来或现在：极高细节的写实摄影，可能带有推测性质，包含天气、磨损和生命轨迹——最后一个时代的真实光线投射其上。";
    transition-between-eras: "面板边缘呈现幽灵般的重写本效果，旧形式的轮廓引导新形式，如同成长的长时间曝光。";
}

